<?php
declare(strict_types=1);
require __DIR__.'/integration_support.php';
use Athar\Learning\UpcomingLessonService;
use Athar\Http\ApiError;

$checks=0;
function event_assert(bool $condition,string $label):void{global $checks;$checks++;if(!$condition)throw new RuntimeException('FAIL: '.$label);}
function event_denied(callable $call,int $status,string $label):void{try{$call();}catch(ApiError $e){event_assert($e->status===$status,$label);return;}event_assert(false,$label);}

isolated_database(static function(PDO $db):void{
    $password=password_hash('UpcomingFixture123!',PASSWORD_DEFAULT);
    foreach(['reader','other','admin'] as $name)$db->prepare('INSERT INTO users(email,username,display_name,password_hash,role,email_verified_at) VALUES (?,?,?,?,?,UTC_TIMESTAMP())')->execute([$name.'@example.test',$name,$name,$password,$name==='admin'?'admin':'user']);
    $db->exec("INSERT INTO scholars(name,is_published) VALUES('Public fixture',1),('Hidden fixture',0)");
    $db->exec("INSERT INTO series(scholar_id,title,is_published) VALUES(1,'Event series fixture',1)");
    for($i=1;$i<=60;$i++)$db->prepare("INSERT INTO lessons(scholar_id,series_id,title,description,youtube_id,source_url,is_published) VALUES(?,1,?,'Fixture only',?,'https://example.invalid/source',1)")->execute([$i===2?null:($i===4?2:1),'درس اختبار '.$i,sprintf('Event%06d',$i)]);
    $service=new UpcomingLessonService($db);
    $admin=['id'=>3,'role'=>'admin','email_verified_at'=>'2026-01-01','suspended_at'=>null];
    $reader=['id'=>1,'role'=>'user','email_verified_at'=>'2026-01-01'];
    $base=['expected_revision'=>0,'status'=>'scheduled','scheduled_at'=>'2030-06-01T20:00:00+03:00','schedule_timezone'=>'Africa/Cairo','reminders_enabled'=>true];
    event_assert($service->page()['items']===[],'migration never invents events for existing content');
    event_assert((int)$db->query('SELECT COUNT(*) FROM lessons WHERE is_published=1')->fetchColumn()===60,'migration preserves prior publication');
    event_denied(fn()=>$service->save($reader,1,$base),403,'ordinary users cannot schedule lessons');
    event_denied(fn()=>$service->save(array_merge($admin,['email_verified_at'=>null]),1,$base),403,'unverified admin denied');
    event_denied(fn()=>$service->save(array_merge($admin,['suspended_at'=>'2026-01-01']),1,$base),403,'suspended admin denied');
    event_denied(fn()=>$service->save($admin,1,['status'=>'scheduled']),422,'mutation requires a revision');
    event_denied(fn()=>$service->save($admin,1,array_merge($base,['scheduled_at'=>'2030-06-01 20:00:00'])),422,'ambiguous wall time rejected');
    event_denied(fn()=>$service->save($admin,1,array_merge($base,['scheduled_at'=>'2030-02-30T20:00:00Z'])),422,'normalized invalid date rejected');
    event_denied(fn()=>$service->save($admin,1,array_merge($base,['schedule_timezone'=>'Unknown/Zone'])),422,'unknown timezone rejected');
    event_denied(fn()=>$service->save($admin,1,array_merge($base,['reminders_enabled'=>null])),422,'boolean null is not silently accepted');
    event_denied(fn()=>$service->save($admin,1,array_merge($base,['estimated_duration_minutes'=>'20'])),422,'duration requires an integer');
    event_denied(fn()=>$service->save($admin,1,['expected_revision'=>0,'status'=>'published']),422,'published event requires canonical start');
    event_denied(fn()=>$service->save($admin,1,array_merge($base,['status'=>'live'])),422,'recorded event cannot claim live');
    event_denied(fn()=>$service->save($admin,1,array_merge($base,['private_worship_segment'=>'inactive users'])),422,'unsupported targeting fields rejected');
    $created=$service->save($admin,1,array_merge($base,['title_ar'=>'درس اختبار قادم','title_en'=>'Upcoming fixture']));
    event_assert($created['revision']===1&&$created['scheduled_at']==='2030-06-01T17:00:00.000Z','explicit offset canonicalizes to UTC independently of host zone');
    event_assert($created['status']==='scheduled'&&!$created['can_watch'],'scheduled metadata does not enable playback');
    event_assert((int)$db->query('SELECT is_published FROM lessons WHERE id=1')->fetchColumn()===0,'future lesson stays out of legacy published catalog');
    event_denied(fn()=>(new \Athar\Catalog\CatalogService($db))->detail('lessons',1),404,'ordinary lesson detail cannot expose an unpublished event');
    event_assert($service->detail(1)['title']==='درس اختبار قادم','Arabic is canonical content');
    $english=$service->detail(1,'en');
    event_assert($english['title']==='Upcoming fixture'&&$english['content_language']==='en'&&$english['description']===null,'English translation does not silently append Arabic description');
    event_assert((int)$db->query('SELECT COUNT(*) FROM activity_events')->fetchColumn()===0,'browsing events never invents worship activity');
    event_assert((bool)preg_match('/^\d{4}-\d{2}-\d{2}T/',$service->page()['server_now']),'response includes a real server instant, not persisted countdown text');
    $second=$service->save($admin,2,array_merge($base,['scheduled_at'=>'2020-01-01T00:00:00Z']));
    event_assert($second['status']==='scheduled'&&$second['scholar_id']===1,'past schedule remains scheduled and inherits scholar');
    $rescheduled=$service->save($admin,1,['expected_revision'=>1,'scheduled_at'=>'2030-06-01T21:00:00+03:00']);
    event_assert($rescheduled['revision']===2&&$rescheduled['scheduled_at']==='2030-06-01T18:00:00.000Z','reschedule advances UTC revision');
    $fact=$db->query('SELECT change_type,payload_json FROM lesson_event_changes WHERE event_id=1 AND revision=2')->fetch();
    $payload=json_decode($fact['payload_json'],true);
    event_assert($fact['change_type']==='rescheduled'&&$payload['previous_scheduled_at']==='2030-06-01T17:00:00.000Z','durable change fact preserves obsolete schedule for invalidation');
    event_denied(fn()=>$service->save($admin,1,['expected_revision'=>1,'title_ar'=>'Stale overwrite']),409,'stale editor cannot overwrite current event');
    event_assert((int)$db->query('SELECT COUNT(*) FROM lesson_event_changes WHERE event_id=1')->fetchColumn()===2,'stale replay adds no duplicate change');
    event_assert($service->detail(1)['title']==='درس اختبار قادم','stale mutation leaves content unchanged');
    $live=$service->save($admin,1,['expected_revision'=>2,'status'=>'live','is_live_event'=>true]);
    event_assert($live['status']==='live'&&$live['can_watch']&&$live['live_source']==='admin'&&$live['live_confirmed_at']!==null,'live requires explicit authoritative action and records provenance');
    event_assert($service->page()['items'][0]['id']===1,'confirmed live has temporal priority');
    event_denied(fn()=>$service->save($admin,1,['expected_revision'=>3,'replay_available'=>true]),422,'live event does not fabricate replay availability');
    event_denied(fn()=>$service->save($admin,1,['expected_revision'=>3,'status'=>'scheduled']),422,'live state cannot silently roll back to scheduled');
    $replay=$service->save($admin,1,['expected_revision'=>3,'status'=>'published','replay_available'=>true]);
    event_assert($replay['can_watch']&&$replay['replay_available'],'published replay becomes watchable');
    event_assert(!in_array(1,array_column($service->page()['items'],'id'),true),'archived replay leaves upcoming list');
    event_denied(fn()=>$service->save($admin,1,['expected_revision'=>4,'status'=>'scheduled']),422,'published replay is not repurposed as a new scheduled occurrence');
    $service->save($admin,1,['expected_revision'=>4,'status'=>'draft','replay_available'=>false]);
    event_denied(fn()=>$service->detail(1),404,'draft hides public event detail');
    $cancelled=$service->save($admin,2,['expected_revision'=>1,'status'=>'cancelled']);
    event_assert($cancelled['status']==='cancelled'&&!$cancelled['can_watch'],'cancellation stops watchability');
    event_assert($service->detail(2)['status']==='cancelled','subscribers can resolve cancellation instead of stale schedule');
    event_denied(fn()=>$service->save($admin,2,['expected_revision'=>2,'status'=>'live','is_live_event'=>true]),422,'cancelled event requires rescheduling before live');
    $service->save($admin,3,array_merge($base,['visibility'=>'private']));
    event_denied(fn()=>$service->detail(3),404,'private event cannot be enumerated through public detail');
    event_assert($service->detail(3,'ar',$admin)['visibility']==='private','authorized admin can edit private draft metadata');
    $service->save($admin,4,$base);
    event_denied(fn()=>$service->detail(4),404,'hidden direct scholar suppresses upcoming event');
    for($i=5;$i<=60;$i++)$service->save($admin,$i,$base);
    $page=$service->page(['per_page'=>500]);$tail=$service->page(['per_page'=>50,'page'=>2]);
    event_assert(count($page['items'])===50&&count($tail['items'])===6,'upcoming pagination is bounded and complete');
    event_assert(array_column($page['items'],'id')===range(5,54)&&array_column($tail['items'],'id')===range(55,60),'tied timestamps use stable event ordering');
    $noReplay=$service->save($admin,60,['expected_revision'=>1,'status'=>'published','is_live_event'=>true,'replay_available'=>false]);
    event_assert(!$noReplay['can_watch'],'an ended live event without an available replay is not a playable archive');
    event_assert((int)$db->query('SELECT is_published FROM lessons WHERE id=60')->fetchColumn()===0,'unavailable replay cannot leak through ordinary watch catalog');
    $db->exec('UPDATE series SET is_published=0 WHERE id=1');
    event_assert($service->page()['items']===[],'hidden parent series suppresses all descendants');
    event_assert($service->page([], 'ar',$admin)['pagination']['total']===60,'admin catalog can inspect hidden ancestry without a public leak');
    $db->exec('UPDATE series SET is_published=1 WHERE id=1');
    $key=random_bytes(32);$auth=new \Athar\Identity\AuthService($db,new \Athar\Identity\OtpService($db,$key,static fn()=>false));
    $kernel=new \Athar\Http\ApiKernel($db,$auth,new \Athar\Identity\RateLimiter($db,$key));
    $headers=['Authorization'=>'Bearer '.$auth->login('reader@example.test','UpcomingFixture123!')['session']['access_token']];
    $adminHeaders=['Authorization'=>'Bearer '.$auth->login('admin@example.test','UpcomingFixture123!')['session']['access_token']];
    event_assert($kernel->handle(new \Athar\Http\Request('GET','/api/v1/upcoming-lessons'))->status===401,'native event route requires authentication');
    event_assert($kernel->handle(new \Athar\Http\Request('GET','/api/v1/upcoming-lessons',[],$headers))->status===200,'verified reader can browse events');
    event_assert($kernel->handle(new \Athar\Http\Request('GET','/api/v1/admin/lesson-events',[],$headers))->status===403,'admin listing rejects ordinary reader');
    event_assert($kernel->handle(new \Athar\Http\Request('GET','/api/v1/admin/lesson-events',[],$adminHeaders))->status===200,'verified admin route works');
    $changed=$kernel->handle(new \Athar\Http\Request('PUT','/api/v1/admin/lessons/5/event',['expected_revision'=>1,'status'=>'cancelled'],$adminHeaders));
    event_assert($changed->status===200&&$changed->body['data']['revision']===2,'admin mutation route applies revision checks');
    event_assert($kernel->handle(new \Athar\Http\Request('GET','/api/v1/upcoming-lessons/5',[],$headers))->body['data']['status']==='cancelled','reader sees actual post-admin state');
});
echo 'PASS: '.$checks." upcoming/state/UTC/visibility/CAS/change-fact/authorization assertions.\n";
